window.CARD_TEMPLATES = window.CARD_TEMPLATES || {};

(function() {

  function t4NormalizeKey(str) {
    return str.toLowerCase().replace(/[^a-z0-9]/g, "_").replace(/_+/g, "_");
  }

  function t4GetField(student, ...possibleKeys) {
    const studentKeys = Object.keys(student);
    for (const wanted of possibleKeys) {
      const match = studentKeys.find(k => t4NormalizeKey(k) === wanted);
      if (match && student[match]) return student[match];
    }
    return "";
  }

  const T4_LOGO_URI = "data:image/jpeg;base64,";
  const T4_SIGNATURE_URI = "data:image/png;base64,";

  window.CARD_TEMPLATES["template_4"] = {

    orientation: "landscape",

    renderFront: function(student, schoolInfo, options) {
      const s = student;
      const schoolCode = options.schoolCode || "";

      const classSection = s.Section ? `${s.Class} - ${s.Section}` : (s.Class || "");
      const dob     = t4GetField(s, "dob");
      const father  = t4GetField(s, "father_s_name", "fathers_name", "father_name");
      const phone   = t4GetField(s, "phone", "contact", "mobile");
      const address = t4GetField(s, "address");

      const photo = s["Photo_Link"]
        ? `<img class="t4-photo-img" src="${getPhotoUrl(s['Photo_Link'], 'w_200,h_200,c_fill')}">`
        : `<div class="t4-photo-placeholder">&lt;Photo&gt;</div>`;

      const now = new Date();
      const sessionLabel = `${now.getFullYear()}-${(now.getFullYear() + 1).toString().slice(-2)}`;

      return `
        <div class="t4-front">

          <div class="t4-header">
            <img class="t4-logo" src="${T4_LOGO_URI}">
            <div class="t4-header-text">
              <div class="t4-school-name">${schoolInfo.school_name || schoolCode}</div>
              <div class="t4-school-address">${schoolInfo.address || ""}</div>
            </div>
          </div>

          <div class="t4-yellow-strip"></div>

          <div class="t4-topline">
            ${schoolInfo.contact ? `<div class="t4-mob">Mob.: ${schoolInfo.contact}</div>` : `<div></div>`}
            <div class="t4-idcard-badge">IDENTITY CARD : ${sessionLabel}</div>
          </div>

          <div class="t4-body">

            <div class="t4-left">
              <div class="t4-photo-wrap">${photo}</div>
            </div>

            <div class="t4-right">
              <div class="t4-row t4-row-name">
                <span class="t4-k">Student's Name:</span>
                <span class="t4-v t4-name-value">${s.Name || ""}</span>
              </div>
              ${father  ? `<div class="t4-row"><span class="t4-k">F. Name:</span><span class="t4-v">${father}</span></div>` : ""}
              ${phone   ? `<div class="t4-row"><span class="t4-k">Mobile No.:</span><span class="t4-v">${phone}</span></div>` : ""}
              ${dob     ? `<div class="t4-row"><span class="t4-k">DOB:</span><span class="t4-v">${dob}</span></div>` : ""}
              ${address ? `<div class="t4-row"><span class="t4-k">Address:</span><span class="t4-v">${address}</span></div>` : ""}
            </div>

            <div class="t4-class-wrap">
              <div class="t4-class-label">Class</div>
              <div class="t4-burst">
                <div class="t4-burst-value">${classSection}</div>
              </div>
            </div>

          </div>

          <div class="t4-footer">
            <div class="t4-sig-block">
              <img class="t4-sig" src="${T4_SIGNATURE_URI}">
              <div class="t4-sig-label">Principal</div>
            </div>
          </div>

        </div>
      `;
    },

    renderBack: function(schoolInfo) {
      return `
        <div class="t4-back">
          <div class="t4-back-title">INSTRUCTIONS</div>
          <ul class="t4-back-list">
            <li>This card is the property of ${schoolInfo.school_name || "the school"}.</li>
            <li>This card is non-transferable.</li>
            <li>Report loss of card immediately.</li>
            <li>This card must be worn within the school premises.</li>
            <li>Return this card when leaving the school.</li>
          </ul>
          <div class="t4-back-footer">
            <div>${schoolInfo.school_name || ""}</div>
            <div>${schoolInfo.address || ""}</div>
            <div>${schoolInfo.contact || ""}</div>
          </div>
        </div>
      `;
    }
  };

})();